def savings_plan(weeks, first, step):
    total = 0
    for i in range(weeks):
        total += first + i * step
    return total

def months_to_goal(balance, goal, monthly):
    months = 0
    while balance < goal:
        balance += monthly
        months += 1
    return months

def clean_phone(text):
    result = ""
    for ch in text:
        if ch == "#":
            break
        if not ch.isdigit():
            continue
        result += ch
    return result

